import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.BW2T23B9.js";const c="/docs/images/authoring/_real/11-settings-ai.png",b=JSON.parse('{"title":"AI 课程生成（创作者视角）","description":"每条主路径都贯穿这 5 类。下文 §2 给出 A–E 路径的步骤表与 GUI 入口映射。","frontmatter":{"description":"每条主路径都贯穿这 5 类。下文 §2 给出 A–E 路径的步骤表与 GUI 入口映射。"},"headers":[],"relativePath":"authoring/ai-course-generation.md","filePath":"authoring/ai-course-generation.md","lastUpdated":1787830168000}'),r={name:"authoring/ai-course-generation.md"};function s(n,t,i,l,p,h){return e(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="ai-课程生成-创作者视角" tabindex="-1">AI 课程生成（创作者视角） <a class="header-anchor" href="#ai-课程生成-创作者视角" aria-label="Permalink to &quot;AI 课程生成（创作者视角）&quot;">​</a></h1><blockquote><p>AI 是创作助手的默认环境语言。本文是 GUI 内所有 AI 能力的入口索引：5 大类、5 条主路径、3 张决策矩阵、字段表与 telemetry 清单。各模块的字段合同详见各专题文档；开发者向深度报告见应用仓库 <code>tool/gui/docs/ai_configuration_and_features_report.md</code>。</p><p>5 大类按创作者工作流排列：<strong>抽取 → 生成 → 编辑 → 修复 → 发布</strong>。每类均给 GUI 入口、字段表、失败模式与不下放边界。</p></blockquote><h2 id="_0-能力全景" tabindex="-1">0. 能力全景 <a class="header-anchor" href="#_0-能力全景" aria-label="Permalink to &quot;0. 能力全景&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                ┌──── 课程工坊（项目库 + 三栏画布）────────────────────┐</span></span>
<span class="line"><span>                │                                                       │</span></span>
<span class="line"><span>                │  1.1 课程生成   1.4 知识抽取   1.3 节点编辑  1.2 修复 │</span></span>
<span class="line"><span>                │                                                       │</span></span>
<span class="line"><span>                └───────────────────────┬───────────────────────────────┘</span></span>
<span class="line"><span>                                        │ 草稿 / 修复 patch</span></span>
<span class="line"><span>                                        ▼</span></span>
<span class="line"><span>   工具栏（主窗口）─────────────────────────────────────────────</span></span>
<span class="line"><span>   课程仓库 / 保存 / 课程工坊 / 总览 / 资源库 / 发布 / 生成听力音频</span></span>
<span class="line"><span>   / 教师模式 / 设置（8 tab）</span></span>
<span class="line"><span>                                        │</span></span>
<span class="line"><span>                                        ▼</span></span>
<span class="line"><span>                          1.5 设置与运维（双模型 / 缓存 / 用量）</span></span></code></pre></div><p>每条主路径都贯穿这 5 类。下文 §2 给出 A–E 路径的步骤表与 GUI 入口映射。</p><h2 id="_1-5-大能力类" tabindex="-1">1. 5 大能力类 <a class="header-anchor" href="#_1-5-大能力类" aria-label="Permalink to &quot;1. 5 大能力类&quot;">​</a></h2><h3 id="_1-1-课程生成-工坊" tabindex="-1">1.1 课程生成（工坊） <a class="header-anchor" href="#_1-1-课程生成-工坊" aria-label="Permalink to &quot;1.1 课程生成（工坊）&quot;">​</a></h3><p>入口：工具栏 <strong>课程工坊</strong>。非模态窗口，承载项目库 + 三栏画布。</p><table tabindex="0"><thead><tr><th>维度</th><th>能力</th></tr></thead><tbody><tr><td>项目模式</td><td>教材项目（PDF/Word/TXT/MD/图片 → 抽取 → Grounded 编排）/ 空白 AI 项目（无教材自由生成）</td></tr><tr><td>生成模式</td><td>快速（整节一次出）/ 精修（Plan → 大纲 → 分课 → 校验 → 内容质量分 → 修复 → 通俗解释 → ReadyImport）</td></tr><tr><td>双模型</td><td><code>ai_model_chat</code>（对话 / 解释）+ <code>ai_model_json</code>（结构化 JSON）分流；缺省同 <code>ai_model</code></td></tr><tr><td>Grounded 选词</td><td>AI 优先从气泡池（≤ 200）选词；池外新词打 <code>new</code> 标签</td></tr><tr><td>多模板</td><td><code>[genre]</code> 标记切预设（<code>general</code> / <code>grammar</code> / <code>dialogue</code> / <code>reading</code>）</td></tr><tr><td>局部重生成</td><td>右键 Unit / Lesson → 局部重生成；可应用前看 diff</td></tr><tr><td>续作</td><td><code>project.json</code> 持久化大纲 / 草稿 / 聊天；中断后从大纲续跑</td></tr><tr><td>Prompt 模板库</td><td>持久化模板 + 使用历史；语言对内置（Turkish ↔ Chinese 含元音和谐 / 敬语 / NFKC 校验）</td></tr><tr><td>并行度</td><td><code>ai_max_parallel_lessons</code> 1–8（默认 1）</td></tr><tr><td>Pipeline 模式</td><td><code>ai_pipeline_default_mode</code> <code>fast</code>（默认）/ <code>refine</code></td></tr></tbody></table><p>实现入口：<code>src/backend/ai_pipeline.py</code>（状态机）/ <code>src/backend/ai_phased.py</code>（快速）/ <code>src/backend/ai_generator.py</code>（基础生成）/ <code>src/backend/ai_pedagogy.py</code>（CEFR / 干扰项 prompt 块）。</p><h3 id="_1-2-校验与修复-主窗口" tabindex="-1">1.2 校验与修复（主窗口） <a class="header-anchor" href="#_1-2-校验与修复-主窗口" aria-label="Permalink to &quot;1.2 校验与修复（主窗口）&quot;">​</a></h3><p>入口：保存按钮 / 校验面板 / 加载失败弹窗 / 发布对话框。</p><table tabindex="0"><thead><tr><th>能力</th><th>实现</th><th>入口</th></tr></thead><tbody><tr><td>六维内容质量分</td><td><code>content_quality.py</code> 纯函数；不阻断</td><td>总览 Section 染色 / 校验面板「按质量分修复」</td></tr><tr><td>AI 修正此节点</td><td><code>ai_fixer.fix_node</code>；自动注入 <code>problems[].message</code></td><td>课程树右键 / 校验面板单条</td></tr><tr><td>AI 批量修正</td><td>按节点分批 merge；每节点一条 <code>QUndoCommand</code></td><td>校验面板多选 → AI 自动修正</td></tr><tr><td>AI 加载错误分析</td><td><code>AiErrorAnalyzerDialog</code> 把 traceback + JSON Schema 喂 LLM</td><td>加载失败弹窗 → AI 分析</td></tr><tr><td>工坊任务失败分析</td><td>同上对话框；上下文含工坊步骤</td><td>工坊失败弹窗 → 拟人化分析</td></tr></tbody></table><p>修复约束：</p><ul><li>不删既有 id；任何删 id 操作回滚到修复前。</li><li>修复后必须再走 <code>validate</code>；任何剩余 error 阻断保存。</li><li>AI 修复不改变质量分；质量分仅指导不阻断。</li></ul><h3 id="_1-3-节点编辑-课程树右键" tabindex="-1">1.3 节点编辑（课程树右键） <a class="header-anchor" href="#_1-3-节点编辑-课程树右键" aria-label="Permalink to &quot;1.3 节点编辑（课程树右键）&quot;">​</a></h3><p>入口：课程树右键 → <strong>AI 编辑此 Section/Unit/Lesson</strong> / <strong>AI 修正此…</strong>。</p><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>4 类预设指令</td><td>精简 / 改写 / 增题 / 翻译润色</td></tr><tr><td>自定义指令</td><td>自由文本</td></tr><tr><td>冲突解决</td><td><code>_detect_ai_edit_conflicts</code> 检查 id 增删 / 改写；弹三选一（保留现状 / 采用 AI 建议 / 取消）</td></tr><tr><td>撤销</td><td>走 <code>QUndoStack</code>（<code>AiEditLessonCommand</code> / <code>AiEditUnitCommand</code> / <code>MergeAiSectionCommand</code>）</td></tr><tr><td>强制人工确认</td><td>节点编辑不自动写盘；必须主窗口 <code>Ctrl+S</code></td></tr></tbody></table><p>Telemetry：<code>ai.edit.open</code> / <code>ai.edit.ready</code> / <code>ai.edit.applied</code> / <code>ai.edit.cancelled</code> / <code>ai.edit.merge.cancelled</code> / <code>ai.edit.error</code> / <code>ai.wizard.generate</code> / <code>ai.helper.start</code>。</p><h3 id="_1-4-知识抽取-教材侧" tabindex="-1">1.4 知识抽取（教材侧） <a class="header-anchor" href="#_1-4-知识抽取-教材侧" aria-label="Permalink to &quot;1.4 知识抽取（教材侧）&quot;">​</a></h3><p>入口：工坊左栏 · 教材与章节。</p><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td>4 抽取预设</td><td><code>general</code> / <code>grammar</code> / <code>dialogue</code> / <code>reading</code>（<code>backend/lesson_presets.py</code> 之外的 <code>textbook_presets.py</code>）</td></tr><tr><td>滑窗抽取</td><td>超长章按 <code>window_chars</code>（默认 12000）+ <code>overlap_chars</code>（800）切窗；按规范化 key 去重</td></tr><tr><td>状态灯</td><td>绿 / 黄 / 红 / 灰；带具体问题（空翻译 / 覆盖率低 / 语言混入）</td></tr><tr><td>失败级联</td><td><code>standard</code> 失败 → 自动降级 <code>vocab_only</code> 重试一次；<code>QSettings/textbook/auto_cascade</code> 可关</td></tr><tr><td>按质量重抽</td><td>把本章质量问题回灌 AI，输出完整修正版替换</td></tr><tr><td>OCR</td><td>可选外部依赖（Tesseract / ocrmypdf），GUI 不内置</td></tr><tr><td>语言对模板</td><td>优先级：内存 register &gt; 持久化覆盖 &gt; 内置语言对包 &gt; 内置默认（<code>backend/knowledge_prompt.py</code>）</td></tr><tr><td>抽词对齐</td><td><code>pos</code> 闭集 / 翻译归一化 NFKC / 跨表去重（<code>vocab</code> ↔ <code>expressions</code>）</td></tr></tbody></table><h3 id="_1-5-设置与运维" tabindex="-1">1.5 设置与运维 <a class="header-anchor" href="#_1-5-设置与运维" aria-label="Permalink to &quot;1.5 设置与运维&quot;">​</a></h3><p>入口：工具栏 <strong>设置</strong> → 8 个 tab。</p><p><img src="`+c+`" alt="设置 → AI 配置（实际运行截图：供应商预设 / Base URL / Key / 双模型）" loading="lazy"></p><table tabindex="0"><thead><tr><th>Tab</th><th>关键 AI 能力</th></tr></thead><tbody><tr><td>外观</td><td>浅色 / 深色 + 字体 80–150% 缩放（间接影响 LLM 长上下文渲染）</td></tr><tr><td>AI 配置</td><td>供应商预设（<code>deepseek</code> / <code>openai</code> / <code>moonshot</code> / <code>ollama</code> / <code>custom</code>）；API Key <strong>仅会话内存</strong>；连接测试；JSON Schema 严格度（<code>auto</code> / <code>on</code> / <code>off</code>）；响应缓存 LRU(128) SHA-256 键；reasoning；timeout 5–600 s；temperature 0–2；重试 0–5；<code>max_parallel_lessons</code> 1–8；<code>pipeline_default_mode</code>（<code>fast</code> / <code>refine</code>）</td></tr><tr><td>AI 用量</td><td>今日 / 累计 token；按模型价格估算成本（<code>backend/ai_presets.py</code> 本地计价表）</td></tr><tr><td>提取 Prompt</td><td>语言对抽取规则块的持久化覆盖</td></tr><tr><td>编辑器</td><td>撤销上限 10–500 步；关闭时未保存策略</td></tr><tr><td>体验 OS</td><td>体验模式四档（observer / copilot / active / immersive）+ Immersive 子开关 + 能力开关 + 日配额</td></tr><tr><td>Git 库</td><td>克隆根 / 二进制路径 / 默认语言 / LAN 端口 / 绑定 / token / SSH 私钥</td></tr><tr><td>操作日志</td><td>最近 200 条操作 / 错误回看</td></tr></tbody></table><p>AI 基础参数（<code>Settings.ai_*</code> 字段）：</p><table tabindex="0"><thead><tr><th>字段</th><th>默认</th><th>范围</th><th>含义</th></tr></thead><tbody><tr><td><code>ai_provider</code></td><td><code>custom</code></td><td>5 个枚举</td><td>一键填 Base URL + 默认模型</td></tr><tr><td><code>ai_base_url</code></td><td>（空）</td><td>URL 字符串</td><td>HTTP endpoint；持久化</td></tr><tr><td><code>ai_model</code></td><td>（空）</td><td>模型标识</td><td>主模型；持久化</td></tr><tr><td><code>ai_model_chat</code></td><td>（空）</td><td>模型标识</td><td>对话 / 解释；空 = 用 <code>ai_model</code></td></tr><tr><td><code>ai_model_json</code></td><td>（空）</td><td>模型标识</td><td>JSON 生成 / 修复；空 = 用 <code>ai_model</code></td></tr><tr><td><code>ai_api_key</code></td><td>（空）</td><td>string</td><td><strong>仅内存</strong>；应用退出即销毁</td></tr><tr><td><code>ai_timeout</code></td><td><code>120.0</code> s</td><td>[5, 600]</td><td>请求超时</td></tr><tr><td><code>ai_temperature</code></td><td><code>0.7</code></td><td>[0.0, 2.0]</td><td>采样随机度</td></tr><tr><td><code>ai_retry_max</code></td><td><code>1</code></td><td>[0, 5]</td><td>自动重试轮数</td></tr><tr><td><code>ai_cache_enabled</code></td><td><code>False</code></td><td>bool</td><td>进程内 LRU(128)，键 SHA-256(model, messages, response_format)，不存 API Key</td></tr><tr><td><code>ai_fill_needs_review</code></td><td><code>False</code></td><td>bool</td><td>二趟补全 <code>[待补]</code> / <code>needs-review</code></td></tr><tr><td><code>ai_max_parallel_lessons</code></td><td><code>1</code></td><td>[1, 8]</td><td>精修流水线并行度</td></tr><tr><td><code>ai_pipeline_default_mode</code></td><td><code>fast</code></td><td><code>fast</code> / <code>refine</code></td><td>精修模式默认</td></tr><tr><td><code>ai_json_schema_strict</code></td><td><code>auto</code></td><td><code>auto</code> / <code>on</code> / <code>off</code></td><td><code>auto</code> 首次 400 自动回退 <code>json_object</code>；<code>on</code> 强制 <code>json_schema</code>；<code>off</code> 强制 <code>json_object</code></td></tr></tbody></table><p>实现位置：<code>src/application/settings.py</code>（<code>Settings.ai_*</code> 字段 + QSettings 键映射）+ <code>src/backend/ai_presets.py</code>（5 供应商预设与本地计价表）。</p><h2 id="_2-5-条主路径" tabindex="-1">2. 5 条主路径 <a class="header-anchor" href="#_2-5-条主路径" aria-label="Permalink to &quot;2. 5 条主路径&quot;">​</a></h2><p>README §&quot;创作者五条主路径（AI 感知增强）&quot; 给出的标准工作流。每条都对应具体 GUI 入口与预期体感。</p><table tabindex="0"><thead><tr><th>路径</th><th>步骤</th><th>GUI 入口</th><th>体感</th></tr></thead><tbody><tr><td><strong>A 空白→一节课</strong></td><td>1. 工坊空白项目 2. 主题/等级 3. 快速或精修生成 4. 结构大纲看<strong>生成摘要 + 质量维</strong> 5. 导入</td><td>工坊 → 空白 AI 项目</td><td>不用翻 JSON 也能决定导不导入</td></tr><tr><td><strong>B 教材→课</strong></td><td>1. 从教材新建 2. 抽章（状态灯可见滑窗/降级）3. 勾选入池 4. Grounded 生成 5. 导入</td><td>工坊 → 从教材新建</td><td>抽取失败有自动降级；可「按质量重抽」</td></tr><tr><td><strong>C 改一处</strong></td><td>1. 教师模式题目「AI」/ 树右键 AI 编辑 / Review 局部重生成 2. 预设指令 3. 确认 + Ctrl+Z</td><td>课程树右键 / 试做 AI 按钮</td><td>改题可确认 + Ctrl+Z</td></tr><tr><td><strong>D 校验清零</strong></td><td>1. 校验面板多选问题 2.「AI 自动修正」按节点分批 merge 3. validate</td><td>校验面板</td><td>不必逐条点修</td></tr><tr><td><strong>E 导入后改进</strong></td><td>1. 总览看 section 质量分 2. 回工坊 / 教师定向修 3. 低分课着色提示</td><td>总览 → 跳转</td><td>低分课有着色提示</td></tr></tbody></table><p>实现位置：工坊对话框 <code>src/dialogs/workshop_window.py</code> + 草稿服务 <code>src/backend/experience/</code> 下各 <code>experience_handlers/*.py</code>。</p><h2 id="_3-决策矩阵" tabindex="-1">3. 决策矩阵 <a class="header-anchor" href="#_3-决策矩阵" aria-label="Permalink to &quot;3. 决策矩阵&quot;">​</a></h2><h3 id="_3-1-项目模式-×-生成模式-×-预设-矩阵" tabindex="-1">3.1 项目模式 × 生成模式 × 预设 矩阵 <a class="header-anchor" href="#_3-1-项目模式-×-生成模式-×-预设-矩阵" aria-label="Permalink to &quot;3.1 项目模式 × 生成模式 × 预设 矩阵&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目模式</th><th>抽取预设</th><th>生成模式</th><th>适用</th></tr></thead><tbody><tr><td>教材项目</td><td><code>general</code></td><td>快速</td><td>草稿探索</td></tr><tr><td>教材项目</td><td><code>grammar</code> / <code>dialogue</code> / <code>reading</code></td><td>精修</td><td>发布候选</td></tr><tr><td>空白 AI 项目</td><td>（无抽取）</td><td>快速</td><td>自由探索</td></tr><tr><td>空白 AI 项目</td><td>（无抽取）</td><td>精修</td><td>高质量初始草稿</td></tr></tbody></table><p>精修模式状态机（<code>backend/ai_pipeline.py</code>）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Plan ──► 大纲 ──► 分课生成 ──► 校验 ──► 内容质量分</span></span>
<span class="line"><span>                                         │</span></span>
<span class="line"><span>                                         ▼</span></span>
<span class="line"><span>                            修复（先规则修复，LLM 仅处理剩余 error）</span></span>
<span class="line"><span>                                         │</span></span>
<span class="line"><span>                                         ▼</span></span>
<span class="line"><span>                                  通俗解释 ──► ReadyImport</span></span>
<span class="line"><span>                  （取消时大纲 / 草稿随 project.json 自动保存）</span></span></code></pre></div><p>右栏 checklist 实时显示每步状态（pending / running / done / skipped / failed）。<strong>流水线只到草稿为止</strong>；导入仍走原有「校验 → 目标选择 → diff/merge 预览 → 人工确认」流程，<strong>不</strong>自动导入。</p><h3 id="_3-2-ai-修正-vs-人工修正-矩阵" tabindex="-1">3.2 AI 修正 vs 人工修正 矩阵 <a class="header-anchor" href="#_3-2-ai-修正-vs-人工修正-矩阵" aria-label="Permalink to &quot;3.2 AI 修正 vs 人工修正 矩阵&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>推荐方式</th><th>备注</th></tr></thead><tbody><tr><td>validate error ≤ 3（单节点）</td><td>AI 修正此节点</td><td>单 patch，可撤销</td></tr><tr><td>validate error 4–10（多节点）</td><td>AI 批量修正</td><td>按节点分批；每批走 <code>QUndoCommand</code></td></tr><tr><td>validate error &gt; 10（跨节）</td><td>拆 Section / 重新生成</td><td>AI 批量修正的批数过多易丢失上下文</td></tr><tr><td>lint warning 连续 3 节同源</td><td>回到工坊按质量重抽</td><td>lint 是结构性偏差，AI 单点修治标</td></tr><tr><td>资源悬挂（<code>unresolved reference</code>）</td><td>资源库手工替换</td><td>AI 不知道该资源的语义边界</td></tr><tr><td>跨 ID 改写</td><td><strong>禁止 AI 自动改</strong></td><td>必须人工；ID 是引用锚点</td></tr></tbody></table><h3 id="_3-3-失败模式-×-降级路径-矩阵" tabindex="-1">3.3 失败模式 × 降级路径 矩阵 <a class="header-anchor" href="#_3-3-失败模式-×-降级路径-矩阵" aria-label="Permalink to &quot;3.3 失败模式 × 降级路径 矩阵&quot;">​</a></h3><table tabindex="0"><thead><tr><th>失败模式</th><th>检测</th><th>降级路径</th></tr></thead><tbody><tr><td>网络失败</td><td>LLM API 超时 / 5xx</td><td>重试 <code>ai_retry_max</code> 轮 → 失败则提示「稍后重试」</td></tr><tr><td>JSON Schema 400</td><td><code>auto</code> 模式</td><td>标记 <code>_json_schema_supported=False</code> → 切 <code>json_object</code></td></tr><tr><td>配额耗尽</td><td>402 / 429</td><td>提示续费；不自动重试</td></tr><tr><td>抽取失败（standard）</td><td>状态灯红</td><td>自动降级 <code>vocab_only</code> 重试一次（默认开）</td></tr><tr><td>抽取失败（vocab_only）</td><td>仍红</td><td>标红 + 拟人化分析按钮</td></tr><tr><td>LLM 返回包含已删 id</td><td><code>_detect_ai_edit_conflicts</code></td><td>弹三选一冲突解决；不得自动应用</td></tr><tr><td>LLM 产出不合 validate</td><td>修复阶段</td><td>先规则修复，LLM 仅处理剩余 error</td></tr><tr><td>TTS 生成失败</td><td>MiniMax API 4xx / 网络失败</td><td>无自动 fallback；失败项记 telemetry，人工处置</td></tr></tbody></table><h2 id="_4-字段表" tabindex="-1">4. 字段表 <a class="header-anchor" href="#_4-字段表" aria-label="Permalink to &quot;4. 字段表&quot;">​</a></h2><h3 id="_4-1-模型配置" tabindex="-1">4.1 模型配置 <a class="header-anchor" href="#_4-1-模型配置" aria-label="Permalink to &quot;4.1 模型配置&quot;">​</a></h3><p>见 §1.5 表格。补充：</p><ul><li><p><strong>供应商预设</strong>（<code>backend/ai_presets.py</code>）：</p><details class="details custom-block"><summary>五个预设对照</summary><table tabindex="0"><thead><tr><th>预设标识</th><th>显示名称</th><th>默认 Base URL</th><th>默认模型</th><th>推理链支持</th></tr></thead><tbody><tr><td><code>deepseek</code></td><td>DeepSeek</td><td><code>https://api.deepseek.com</code></td><td><code>deepseek-v4-pro</code></td><td>是</td></tr><tr><td><code>openai</code></td><td>OpenAI</td><td><code>https://api.openai.com/v1</code></td><td><code>gpt-4o</code></td><td>否</td></tr><tr><td><code>moonshot</code></td><td>Moonshot AI</td><td><code>https://api.moonshot.cn/v1</code></td><td><code>moonshot-v1-8k</code></td><td>否</td></tr><tr><td><code>ollama</code></td><td>Ollama（本地）</td><td><code>http://localhost:11434/v1</code></td><td><code>qwen2.5</code></td><td>否</td></tr><tr><td><code>custom</code></td><td>自定义</td><td>用户填写</td><td>用户填写</td><td>用户勾选</td></tr></tbody></table></details></li><li><p><strong>JSON Schema 严格度</strong>：<code>auto</code>（默认）首次 <code>json_schema</code> 试错遇 400 时调用 <code>mark_json_schema_unsupported()</code>，后续切 <code>json_object</code>；<code>on</code> 强制 <code>json_schema</code>；<code>off</code> 强制 <code>json_object</code>。</p></li><li><p><strong>响应缓存</strong>：进程内 LRU(128)；命中仍会跑 validator 防脏；<code>ai.cache.stats</code> 事件给出命中/未命中计数。</p></li></ul><h3 id="_4-2-抽取预设" tabindex="-1">4.2 抽取预设 <a class="header-anchor" href="#_4-2-抽取预设" aria-label="Permalink to &quot;4.2 抽取预设&quot;">​</a></h3><details class="details custom-block"><summary>四个预设对照</summary><table tabindex="0"><thead><tr><th>预设</th><th>目标</th><th>提示词倾向</th><th>实现</th></tr></thead><tbody><tr><td><code>general</code></td><td>通用教材</td><td>均衡抽取</td><td><code>backend/textbook_presets.py</code></td></tr><tr><td><code>grammar</code></td><td>语法书</td><td>低温度，强调规则</td><td>同上</td></tr><tr><td><code>dialogue</code></td><td>对话书</td><td>强调表达与口语</td><td>同上</td></tr><tr><td><code>reading</code></td><td>阅读材料</td><td>词汇抽取为主</td><td>同上</td></tr></tbody></table></details><h3 id="_4-3-内容质量六维" tabindex="-1">4.3 内容质量六维 <a class="header-anchor" href="#_4-3-内容质量六维" aria-label="Permalink to &quot;4.3 内容质量六维&quot;">​</a></h3><p><code>backend/content_quality.py</code> 纯函数；不依赖 Qt。每维 0–1，越高越好；默认阈值 0.7。</p><details class="details custom-block"><summary>六维探针对照</summary><table tabindex="0"><thead><tr><th>维度</th><th>探针</th><th style="text-align:right;">阈值</th><th>不阻断</th></tr></thead><tbody><tr><td>复现（reproducibility）</td><td>同 prompt 多 LLM 输出 JSON Schema 一致性</td><td style="text-align:right;">≥ 0.8</td><td>是</td></tr><tr><td>题型（item_type）</td><td>每 stage 题型分布与模板预设一致</td><td style="text-align:right;">≥ 0.7</td><td>是</td></tr><tr><td>干扰项（distractor）</td><td>选项与正确项同 pos、同 cefr、无语义近邻</td><td style="text-align:right;">≥ 0.6</td><td>是</td></tr><tr><td>难度（difficulty）</td><td>同一 stage 内认知梯度单调</td><td style="text-align:right;">≥ 0.7</td><td>是</td></tr><tr><td>听力（listening）</td><td><code>listeningPhases</code> 资产齐全 + 重播按钮 + 文本边界 ≥ 2 s</td><td style="text-align:right;">≥ 0.7</td><td>是</td></tr><tr><td>资源卫生（hygiene）</td><td>词汇 / 表达 / 语法点引用闭环；无孤立条目</td><td style="text-align:right;">≥ 0.8</td><td>是</td></tr></tbody></table></details><h2 id="_5-telemetry-事件表" tabindex="-1">5. Telemetry 事件表 <a class="header-anchor" href="#_5-telemetry-事件表" aria-label="Permalink to &quot;5. Telemetry 事件表&quot;">​</a></h2><p><code>src/infrastructure/telemetry.py</code> 已实现事件（按子系统分组）：</p><details class="details custom-block"><summary>事件全表</summary><table tabindex="0"><thead><tr><th>子系统</th><th>事件</th></tr></thead><tbody><tr><td>仓库</td><td><code>repo.open</code> / <code>repo.new</code> / <code>repo.open.cancelled</code> / <code>repo.new.cancelled</code> / <code>repo.save.triggered</code></td></tr><tr><td>发布</td><td><code>repo.publish.triggered</code> / <code>repo.publish.committed</code> / <code>repo.publish.failed</code></td></tr><tr><td>AI 编辑</td><td><code>ai.edit.open</code> / <code>ai.edit.ready</code> / <code>ai.edit.applied</code> / <code>ai.edit.cancelled</code> / <code>ai.edit.error</code> / <code>ai.edit.merge.cancelled</code> / <code>ai.wizard.generate</code> / <code>ai.helper.start</code></td></tr><tr><td>AI 缓存</td><td><code>ai.cache.stats</code>（命中 / 未命中计数）</td></tr><tr><td>AI 解释</td><td><code>ai.explain.done</code></td></tr><tr><td>AI 生成</td><td><code>ai.generate.start</code></td></tr><tr><td>TTS</td><td><code>tts.open</code> / <code>tts.generate</code> / <code>tts.generate_failed</code></td></tr><tr><td>教材抽取</td><td><code>textbook.extract.cancel</code> / <code>textbook.review.edit</code></td></tr><tr><td>体验</td><td><code>experience.chip.start</code> / <code>experience.palette</code> / <code>overview.open</code> / <code>publish.open</code> / <code>resources.open</code> / <code>settings.open</code> / <code>workshop.open</code> / <code>wizard.open</code> / <code>git_library.open</code></td></tr><tr><td>关闭</td><td><code>app.close_requested</code> / <code>app.close_saved</code> / <code>app.close_discarded</code> / <code>app.close_cancelled</code></td></tr></tbody></table></details><p>所有事件通过 <code>QSettings</code> 持久化在设置 → 操作日志 tab 可见。失败类事件走 <code>telemetry.record_error(exc, context=...)</code> 同时记录异常堆栈与上下文。</p><h2 id="_6-与-gui-主窗口的衔接" tabindex="-1">6. 与 GUI 主窗口的衔接 <a class="header-anchor" href="#_6-与-gui-主窗口的衔接" aria-label="Permalink to &quot;6. 与 GUI 主窗口的衔接&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工具栏入口（9 项）：</span></span>
<span class="line"><span>  课程仓库 / 保存 / 课程工坊 / 总览 / 资源库 / 发布 / 生成听力音频 / 教师模式 / 设置</span></span>
<span class="line"><span></span></span>
<span class="line"><span>课程树右键入口（17 动作）：</span></span>
<span class="line"><span>  Section  → 新建 Unit / 删除 / AI 编辑此 / AI 修正此</span></span>
<span class="line"><span>  Unit     → 新建 Lesson / 功能课向导… / 删除 / AI 编辑 / AI 修正</span></span>
<span class="line"><span>  Lesson   → 复制 (Ctrl+D) / 删除 / AI 编辑 / AI 修正</span></span>
<span class="line"><span>  多选     → 批量复制 / 批量移动 / 批量套用预设 / 批量删除</span></span>
<span class="line"><span></span></span>
<span class="line"><span>资源库菜单（2 项）：</span></span>
<span class="line"><span>  本地资源（3 标签）</span></span>
<span class="line"><span>  Git 资源库（3 标签：远程协作 / LAN / 团队留言板）</span></span></code></pre></div><p>工坊画布入口的细节见 <a href="/docs/authoring/textbook-import">教材导入</a> 与 <a href="/docs/authoring/teacher-guide#4-课程工坊可选">教师指南 - 课程工坊</a>。</p><h2 id="_7-失败模式与降级路径" tabindex="-1">7. 失败模式与降级路径 <a class="header-anchor" href="#_7-失败模式与降级路径" aria-label="Permalink to &quot;7. 失败模式与降级路径&quot;">​</a></h2><h3 id="_7-1-网络失败" tabindex="-1">7.1 网络失败 <a class="header-anchor" href="#_7-1-网络失败" aria-label="Permalink to &quot;7.1 网络失败&quot;">​</a></h3><ul><li>检测：HTTP 超时 / 5xx / DNS 失败。</li><li>降级：重试 <code>ai_retry_max</code> 轮（指数退避），全部失败后弹「稍后重试」并写入 telemetry。</li></ul><h3 id="_7-2-schema-失败" tabindex="-1">7.2 Schema 失败 <a class="header-anchor" href="#_7-2-schema-失败" aria-label="Permalink to &quot;7.2 Schema 失败&quot;">​</a></h3><ul><li>检测：<code>response_format=json_schema</code> 收到 400 / 含 &quot;schema&quot; 错误。</li><li>降级：调 <code>mark_json_schema_unsupported()</code> 标记；后续自动切 <code>json_object</code>；状态写入 <code>ai.json_schema.strict</code> 字段。</li></ul><h3 id="_7-3-配额失败" tabindex="-1">7.3 配额失败 <a class="header-anchor" href="#_7-3-配额失败" aria-label="Permalink to &quot;7.3 配额失败&quot;">​</a></h3><ul><li>检测：402 / 429 状态码。</li><li>降级：<strong>不</strong>自动重试；提示续费；保留草稿到 <code>project.json</code>；等待人工恢复。</li></ul><h3 id="_7-4-资源悬挂" tabindex="-1">7.4 资源悬挂 <a class="header-anchor" href="#_7-4-资源悬挂" aria-label="Permalink to &quot;7.4 资源悬挂&quot;">​</a></h3><ul><li>检测：lint 报 <code>unresolved reference</code>。</li><li>处置：资源库手工替换；<strong>不</strong>调 AI 补建（AI 不知道该资源的语义边界）。</li></ul><h3 id="_7-5-工坊任务失败" tabindex="-1">7.5 工坊任务失败 <a class="header-anchor" href="#_7-5-工坊任务失败" aria-label="Permalink to &quot;7.5 工坊任务失败&quot;">​</a></h3><ul><li>检测：工坊任务状态机跳到 <code>failed</code>。</li><li>降级：弹 <code>AiErrorAnalyzerDialog</code> 拟人化分析；保留草稿；允许续作。</li></ul><h3 id="_7-6-tts-失败" tabindex="-1">7.6 TTS 失败 <a class="header-anchor" href="#_7-6-tts-失败" aria-label="Permalink to &quot;7.6 TTS 失败&quot;">​</a></h3><ul><li>检测：MiniMax API 4xx / 网络失败 / 子进程非零退出。</li><li>降级：无自动 fallback 链；失败项记 <code>telemetry</code>，明细在设置 → 操作日志查看；该 phase 保留文本，发布前补录或重试。</li></ul><h2 id="_8-创作者不下放的边界" tabindex="-1">8. 创作者不下放的边界 <a class="header-anchor" href="#_8-创作者不下放的边界" aria-label="Permalink to &quot;8. 创作者不下放的边界&quot;">​</a></h2><p>硬规则，AI 任何场景都不得越界：</p><ol><li>不让 AI 改既有节点的 <code>id</code>。</li><li>不让 AI 删既有 <code>vocab</code> / <code>expression</code> / <code>grammar_point</code>。</li><li>不让 AI 自动覆盖既有 Section（必须人工选合并 / 跳过 / 覆盖 / 作为新 Section）。</li><li>不让 AI 在共享目录自动写盘（仅在 <code>course_dir</code> 内允许）。</li><li>不让 AI 在没有作者 review 的情况下进入发布（必须主窗口 <code>Ctrl+S</code>）。</li><li>不让 AI 跳过 <code>validate</code> 与 <code>lint</code>。</li><li>不让 AI 替换为未注册的 <code>runtimeType</code>。</li><li>不让 AI 跨越语言对边界（如 <code>tr</code> 课程引用 <code>en</code> 课程的 <code>vocab</code>）。</li></ol><p>违反上述任一条的 AI 输出必须由作者裁决，不得静默应用。</p><blockquote><p>AI 的「下不下放」由 4 档体验模式（observer / copilot / active / immersive）控制。<code>PolicyDecision</code> 字段、M-08 配额熔断、LLM 意图分类与 <code>Ctrl+Shift+D</code> 一键降档见 <a href="/docs/authoring/ai-control-modes">AI 控制模式</a>。</p></blockquote><h2 id="_9-相关文档" tabindex="-1">9. 相关文档 <a class="header-anchor" href="#_9-相关文档" aria-label="Permalink to &quot;9. 相关文档&quot;">​</a></h2><ul><li><a href="/docs/authoring/teacher-guide">教师指南</a></li><li><a href="/docs/authoring/course-layout">课程目录约定</a></li><li><a href="/docs/authoring/resource-files">资源文件</a></li><li><a href="/docs/authoring/lesson-schema">Lesson JSON 结构</a></li><li><a href="/docs/authoring/validation">校验与 Lint</a></li><li><a href="/docs/authoring/textbook-import">教材导入</a></li><li><a href="/docs/authoring/audio-assets">音频资产</a></li><li><a href="/docs/authoring/release-checklist">发布检查表</a></li><li>应用仓库 <code>tool/gui/docs/ai_configuration_and_features_report.md</code>（开发者向深度报告）</li><li>应用仓库 <code>tool/gui/docs/ai_refactor_contract.md</code>（AI 重构契约）</li></ul>`,79)])])}const u=d(r,[["render",s]]);export{b as __pageData,u as default};
